    position: fixed; inset: 0; pointer-events: none;
    background: radial-gradient(ellipse at 50% 42%, rgba(0,0,0,0) 55%, rgba(10,4,24,0.55) 100%);
  }
  .title {
    position: fixed; left: 50%; bottom: 4.5vh; transform: translateX(-50%);
    text-align: center; pointer-events: none; user-select: none;
    color: #f8e7d8; font-family: 'Noto Serif JP', serif;
    text-shadow: 0 2px 18px rgba(20,8,40,.8);
  }
  .title .jp { display: block; font-size: clamp(22px, 4vw, 42px); font-weight: 300; letter-spacing: .35em; text-indent:.35em; }
  .title .en { display: block; margin-top: .5em; font-size: clamp(10px, 1.4vw, 14px); font-weight: 500; letter-spacing: .5em; text-indent:.5em; opacity: .75; text-transform: uppercase; }
</style>
</head>
